// Package secrets finds API keys, tokens and other credentials in text using
// the betterleaks ruleset, embedded as data (rules.json, generated by
// tools/dlprules from a pinned upstream tag; MIT, see LICENSE.betterleaks).
// The betterleaks scanner itself is not linked, and rules never make network
// calls.
//
// Matching per rule: an Aho-Corasick keyword prefilter over the lowercased
// text picks candidate rules, then the rule's RE2 regex runs, then its
// translated filter and the global placeholder filter discard look-alikes.
// A rule's regex runs only on the lines holding one of its keywords: Go's
// regexp is much faster on short inputs (it can use its backtracker), and a
// match nearly always sits on its keyword's line. The few rules whose regex
// can span lines (PEM private keys, service-account JSON, …) scan the whole
// text. Regexes compile lazily on a rule's first keyword hit, so a helper
// only pays for the rules its users' clipboards actually trigger.
package secrets

import (
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"regexp/syntax"
	"sort"
	"strings"
	"sync"

	"github.com/rrethy/ahocorasick"
)

//go:embed rules.json
var rulesJSON []byte

// maxMatchesPerRule bounds the work one rule does on one chunk of hostile input.
const maxMatchesPerRule = 100

// Source records which upstream ruleset is embedded.
type Source struct {
	Repo   string `json:"repo"`
	Tag    string `json:"tag"`
	Commit string `json:"commit"`
}

// Match is one secret found by a rule. Start and End are byte offsets of the
// secret itself (the rule's secret group), not of the whole regex match.
type Match struct {
	RuleID     string
	Start, End int
}

type filterSpec struct {
	EntropyBelow   float64    `json:"entropy_below"`
	EntropyAtMost  float64    `json:"entropy_at_most"`
	DenyRegex      []string   `json:"deny_regex"`
	DenyContains   []string   `json:"deny_contains_hex"` // hex-encoded; see tools/dlprules
	DenyMatchRegex []string   `json:"deny_match_regex"`
	RequireRegex   [][]string `json:"require_regex"`
}

type ruleSpec struct {
	ID          string      `json:"id"`
	Confidence  string      `json:"confidence"`
	Regex       string      `json:"regex"`
	SecretGroup int         `json:"secret_group"`
	Keywords    []string    `json:"keywords"`
	Filter      *filterSpec `json:"filter"`
}

type rulesetSpec struct {
	Source       Source     `json:"source"`
	GlobalFilter filterSpec `json:"global_filter"`
	Rules        []ruleSpec `json:"rules"`
}

// filter is a compiled filterSpec.
type filter struct {
	entropyBelow, entropyAtMost float64
	deny, denyMatch             []*regexp.Regexp
	denyContains                []string
	require                     [][]*regexp.Regexp
}

type rule struct {
	spec ruleSpec

	once   sync.Once
	re     *regexp.Regexp
	filter *filter
	spans  bool // the regex can match across lines
	err    error
}

// Ruleset is the embedded ruleset, loaded once and shared.
type Ruleset struct {
	source    Source
	rules     []*rule
	byID      map[string]int
	global    *filter
	keywords  *ahocorasick.Matcher
	byKeyword map[string][]int // lowercased keyword -> rule indexes
	always    []int            // rules that can't be prefiltered
}

var (
	loadOnce sync.Once
	loaded   *Ruleset
	errLoad  error
)

// Load returns the embedded ruleset.
func Load() (*Ruleset, error) {
	loadOnce.Do(func() { loaded, errLoad = parse(rulesJSON) })
	return loaded, errLoad
}

func parse(data []byte) (*Ruleset, error) {
	var spec rulesetSpec
	if err := json.Unmarshal(data, &spec); err != nil {
		return nil, fmt.Errorf("secrets: decode rules: %w", err)
	}
	global, err := compileFilter(spec.GlobalFilter)
	if err != nil {
		return nil, fmt.Errorf("secrets: global filter: %w", err)
	}
	rs := &Ruleset{
		source:    spec.Source,
		byID:      make(map[string]int, len(spec.Rules)),
		global:    global,
		byKeyword: map[string][]int{},
	}
	var words []string
	for i, s := range spec.Rules {
		rs.rules = append(rs.rules, &rule{spec: s})
		rs.byID[s.ID] = i
		if len(s.Keywords) == 0 || !allASCII(s.Keywords) {
			// The prefilter lowercases ASCII only (so offsets stay exact);
			// such a rule can't be prefiltered and always runs.
			rs.always = append(rs.always, i)
			continue
		}
		for _, k := range s.Keywords {
			if _, seen := rs.byKeyword[k]; !seen {
				words = append(words, k)
			}
			rs.byKeyword[k] = append(rs.byKeyword[k], i)
		}
	}
	rs.keywords = ahocorasick.CompileStrings(words)
	return rs, nil
}

// Source returns the upstream the ruleset was generated from.
func (rs *Ruleset) Source() Source { return rs.source }

// IDs returns every rule id, sorted.
func (rs *Ruleset) IDs() []string {
	ids := make([]string, 0, len(rs.rules))
	for _, r := range rs.rules {
		ids = append(ids, r.spec.ID)
	}
	sort.Strings(ids)
	return ids
}

// Has reports whether id is a rule in the set.
func (rs *Ruleset) Has(id string) bool {
	_, ok := rs.byID[id]
	return ok
}

// compile builds a rule's regex and filter on first use.
func (r *rule) compile() error {
	r.once.Do(func() {
		if r.re, r.err = regexp.Compile(r.spec.Regex); r.err != nil {
			return
		}
		r.spans = spansLines(r.spec.Regex)
		if r.spec.Filter != nil {
			r.filter, r.err = compileFilter(*r.spec.Filter)
		}
	})
	return r.err
}

// Find returns the secrets in text found by the rules enabled reports true
// for (every rule when enabled is nil).
func (rs *Ruleset) Find(text string, enabled func(id string) bool) []Match {
	idx, hits := rs.candidates(text, enabled)
	lines := newLineIndex(text)
	var out []Match
	for _, i := range idx {
		r := rs.rules[i]
		if r.compile() != nil {
			continue
		}
		if r.spans || hits[i] == nil {
			out = append(out, r.find(text, 0, rs.global)...)
			continue
		}
		for _, ln := range lines.spans(hits[i]) {
			out = append(out, r.find(text[ln[0]:ln[1]], ln[0], rs.global)...)
		}
	}
	return out
}

// candidates returns the enabled rules whose keywords occur in text (plus the
// rules that always run), in rule order, and for each the offsets of its
// keyword hits (nil for rules that always run on the whole text).
func (rs *Ruleset) candidates(text string, enabled func(id string) bool) ([]int, map[int][]int) {
	hits := map[int][]int{}
	for _, i := range rs.always {
		hits[i] = nil
	}
	for _, m := range rs.keywords.FindAllString(asciiLower(text)) {
		for _, i := range rs.byKeyword[string(m.Word)] {
			hits[i] = append(hits[i], m.Index)
		}
	}
	idx := make([]int, 0, len(hits))
	for i := range hits {
		if enabled == nil || enabled(rs.rules[i].spec.ID) {
			idx = append(idx, i)
		}
	}
	sort.Ints(idx) // deterministic order
	return idx, hits
}

// find runs the rule over chunk, which starts at byte base of the text.
func (r *rule) find(chunk string, base int, global *filter) []Match {
	var out []Match
	for _, loc := range r.re.FindAllStringSubmatchIndex(chunk, maxMatchesPerRule) {
		start, end := secretSpan(loc, r.spec.SecretGroup)
		if start < 0 || start == end {
			continue
		}
		secret, match := chunk[start:end], chunk[loc[0]:loc[1]]
		if r.filter.discards(secret, match) || global.discards(secret, match) {
			continue
		}
		out = append(out, Match{RuleID: r.spec.ID, Start: base + start, End: base + end})
	}
	return out
}

// secretSpan picks the secret out of a submatch index: the configured group,
// else the first non-empty group, else the whole match (gitleaks semantics).
func secretSpan(loc []int, group int) (int, int) {
	groups := len(loc)/2 - 1
	if group > 0 {
		if group > groups {
			return -1, -1
		}
		return loc[2*group], loc[2*group+1]
	}
	for g := 1; g <= groups; g++ {
		if loc[2*g] >= 0 && loc[2*g+1] > loc[2*g] {
			return loc[2*g], loc[2*g+1]
		}
	}
	return loc[0], loc[1]
}

// lineIndex maps offsets to the lines holding them.
type lineIndex struct {
	text   string
	starts []int // offset of each line's first byte
}

func newLineIndex(text string) *lineIndex {
	li := &lineIndex{text: text, starts: []int{0}}
	for i := 0; i < len(text); i++ {
		if text[i] == '\n' {
			li.starts = append(li.starts, i+1)
		}
	}
	return li
}

// spans returns the distinct lines (start, end including the newline) that
// hold the given offsets, in order.
func (li *lineIndex) spans(offsets []int) [][2]int {
	sort.Ints(offsets)
	var out [][2]int
	last := -1
	for _, off := range offsets {
		n := sort.Search(len(li.starts), func(k int) bool { return li.starts[k] > off }) - 1
		if n == last {
			continue
		}
		last = n
		end := len(li.text)
		if n+1 < len(li.starts) {
			end = li.starts[n+1]
		}
		out = append(out, [2]int{li.starts[n], end})
	}
	return out
}

// asciiLower lowercases A–Z only, so every byte keeps its offset (unlike
// strings.ToLower, which can change the length of non-ASCII text).
func asciiLower(s string) string {
	b := []byte(s)
	for i, c := range b {
		if 'A' <= c && c <= 'Z' {
			b[i] = c + ('a' - 'A')
		}
	}
	return string(b)
}

func allASCII(words []string) bool {
	for _, w := range words {
		for i := 0; i < len(w); i++ {
			if w[i] >= 0x80 {
				return false
			}
		}
	}
	return true
}

// spansLines reports whether pattern can match across a newline: through "."
// under (?s), or a repetition (unbounded or longer than 3) of something that
// can match "\n". A short optional "\s" between a key and its value doesn't
// count; such a match split over two lines is accepted as missed.
func spansLines(pattern string) bool {
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil {
		return true
	}
	return spans(re.Simplify())
}

func spans(re *syntax.Regexp) bool {
	if re.Op == syntax.OpAnyChar || repeatsNewline(re) {
		return true
	}
	for _, sub := range re.Sub {
		if spans(sub) {
			return true
		}
	}
	return false
}

// repeatsNewline reports whether re is a long or unbounded repetition of
// something that can match "\n".
func repeatsNewline(re *syntax.Regexp) bool {
	switch re.Op {
	case syntax.OpStar, syntax.OpPlus:
		return canMatchNewline(re.Sub[0])
	case syntax.OpRepeat:
		return (re.Max == -1 || re.Max > 3) && canMatchNewline(re.Sub[0])
	default:
		return false
	}
}

func canMatchNewline(re *syntax.Regexp) bool {
	switch re.Op {
	case syntax.OpAnyChar:
		return true
	case syntax.OpCharClass:
		for i := 0; i+1 < len(re.Rune); i += 2 {
			if re.Rune[i] <= '\n' && '\n' <= re.Rune[i+1] {
				return true
			}
		}
	case syntax.OpLiteral:
		for _, c := range re.Rune {
			if c == '\n' {
				return true
			}
		}
	}
	for _, sub := range re.Sub {
		if canMatchNewline(sub) {
			return true
		}
	}
	return false
}

func compileFilter(s filterSpec) (*filter, error) {
	f := &filter{entropyBelow: s.EntropyBelow, entropyAtMost: s.EntropyAtMost}
	for _, h := range s.DenyContains {
		b, err := hex.DecodeString(h)
		if err != nil {
			return nil, fmt.Errorf("deny_contains_hex %q: %w", h, err)
		}
		f.denyContains = append(f.denyContains, string(b))
	}
	var err error
	if f.deny, err = compileAll(s.DenyRegex); err != nil {
		return nil, err
	}
	if f.denyMatch, err = compileAll(s.DenyMatchRegex); err != nil {
		return nil, err
	}
	for _, group := range s.RequireRegex {
		res, err := compileAll(group)
		if err != nil {
			return nil, err
		}
		f.require = append(f.require, res)
	}
	return f, nil
}

func compileAll(patterns []string) ([]*regexp.Regexp, error) {
	out := make([]*regexp.Regexp, 0, len(patterns))
	for _, p := range patterns {
		re, err := regexp.Compile(p)
		if err != nil {
			return nil, fmt.Errorf("compile %q: %w", p, err)
		}
		out = append(out, re)
	}
	return out, nil
}

// discards reports whether f rejects the finding. A nil filter keeps it.
func (f *filter) discards(secret, match string) bool {
	if f == nil {
		return false
	}
	if f.lowEntropy(secret) || anyMatch(f.deny, secret) || anyMatch(f.denyMatch, match) {
		return true
	}
	for _, c := range f.denyContains {
		if strings.Contains(secret, c) {
			return true
		}
	}
	for _, group := range f.require {
		if !anyMatch(group, secret) {
			return true
		}
	}
	return false
}

// lowEntropy reports whether secret is under the filter's entropy threshold.
func (f *filter) lowEntropy(secret string) bool {
	if f.entropyBelow == 0 && f.entropyAtMost == 0 {
		return false
	}
	e := Entropy(secret)
	return (f.entropyBelow > 0 && e < f.entropyBelow) || (f.entropyAtMost > 0 && e <= f.entropyAtMost)
}

func anyMatch(res []*regexp.Regexp, s string) bool {
	for _, re := range res {
		if re.MatchString(s) {
			return true
		}
	}
	return false
}

// Entropy is the Shannon entropy of s in bits per character.
func Entropy(s string) float64 {
	if s == "" {
		return 0
	}
	counts := map[rune]int{}
	n := 0
	for _, c := range s {
		counts[c]++
		n++
	}
	var e float64
	for _, c := range counts {
		p := float64(c) / float64(n)
		e -= p * math.Log2(p)
	}
	return e
}
